SELECT

FROM t_dict_item i
WHERE i.dict_type = #{dictType}
  AND i.del_flag = '0'
ORDER BY i.sort_num, i.id
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM t_dict_item i
WHERE i.dict_type = #{dictType}
  AND i.`value` = #{value}
  AND i.del_flag = '0'

    AND i.id <> #{excludeId}
